head.b:skin:
/* ================================================
   PENA EDUKASI - MODERN BLOGGER TEMPLATE
   ================================================ */

:root {
  --bg-body: #F8F9FA;
  --bg-card: #FFFFFF;
  --bg-sidebar: #fdf2f8;
  --bg-dark: #0f172a;
  --bg-dark-card: #1e293b;
  --bg-dark-sidebar: #1a1230;
  --text-primary: #1e293b;
  --text-secondary: #64748b;
  --text-muted: #94a3b8;
  --text-dark-primary: #f1f5f9;
  --text-dark-secondary: #94a3b8;
  --accent: #1a8a9e;
  --accent-hover: #15707f;
  --accent-light: rgba(26,138,158,0.08);
  --border: #e2e8f0;
  --border-dark: #334155;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 10px 30px rgba(0,0,0,0.1);
  --radius: 12px;
  --radius-sm: 8px;
  --radius-full: 9999px;
  --font-sans: 'Inter',-apple-system,BlinkMacSystemFont,sans-serif;
  --font-serif: 'Playfair Display',Georgia,serif;
  --topbar-h: 56px;
  --sidebar-w: 260px;
  --sidebar-r-w: 310px;
  --ease: cubic-bezier(0.4,0,0.2,1);
  --tr: 0.25s var(--ease);
}

*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;}
body{font-family:var(--font-sans);background:var(--bg-body);color:var(--text-primary);line-height:1.6;-webkit-font-smoothing:antialiased;}
a{color:inherit;text-decoration:none;transition:color var(--tr);}
img{max-width:100%;height:auto;display:block;}
ul,ol{list-style:none;}

/* ========== DARK MODE ========== */
body.dark-mode{background:var(--bg-dark);color:var(--text-dark-primary);}
body.dark-mode .sidebar-left{background:var(--bg-dark-sidebar);border-color:var(--border-dark);}
body.dark-mode .sidebar-brand h2{color:#5eead4;}
body.dark-mode .sidebar-brand p{color:var(--text-dark-secondary);}
body.dark-mode .sidebar-nav a{color:var(--text-dark-secondary);}
body.dark-mode .sidebar-nav a:hover,body.dark-mode .sidebar-nav a.active{background:rgba(26,138,158,0.15);color:#5eead4;}
body.dark-mode .search-box input{background:rgba(255,255,255,0.05);border-color:var(--border-dark);color:var(--text-dark-primary);}
body.dark-mode .topbar{background:var(--bg-dark-card);border-color:var(--border-dark);}
body.dark-mode .pill-nav a{background:var(--bg-dark-card);border-color:var(--border-dark);color:var(--text-dark-secondary);}
body.dark-mode .pill-nav a:hover,body.dark-mode .pill-nav a.active{background:var(--accent);border-color:var(--accent);color:#fff;}
body.dark-mode .pill-arrow{background:var(--bg-dark-card);border-color:var(--border-dark);color:var(--text-dark-secondary);}
body.dark-mode .theme-btn{background:var(--bg-dark-card);border-color:var(--border-dark);color:var(--text-dark-secondary);}
body.dark-mode .sidebar-r-box{background:var(--bg-dark-card);border-color:var(--border-dark);}
body.dark-mode .pop-num{background:rgba(26,138,158,0.2);color:#5eead4;}
body.dark-mode .pop-title{color:var(--text-dark-primary);}
body.dark-mode .pop-date{color:var(--text-dark-secondary);}
body.dark-mode .pop-item{border-color:var(--border-dark);}
body.dark-mode .sb-title{color:var(--text-dark-secondary);}
body.dark-mode .sb-title::after{background:var(--border-dark);}
body.dark-mode .cat-pill{background:rgba(26,138,158,0.15);color:#5eead4;}
body.dark-mode .cat-pill:hover{background:var(--accent);color:#fff;}
body.dark-mode .grid-title{color:var(--text-dark-primary);}
body.dark-mode .main-content-inner{background:var(--bg-dark-card);border-color:var(--border-dark);}
body.dark-mode .article-card{background:var(--bg-dark-card);border-color:var(--border-dark);}
body.dark-mode .card-title a{color:var(--text-dark-primary);}
body.dark-mode .card-excerpt{color:var(--text-dark-secondary);}
body.dark-mode .card-meta{color:var(--text-dark-secondary);border-color:var(--border-dark);}
body.dark-mode .post-wrap{color:var(--text-dark-primary);}
body.dark-mode .post-title-single{color:var(--text-dark-primary);}
body.dark-mode .post-meta-s{color:var(--text-dark-secondary);border-color:var(--border-dark);}
body.dark-mode .post-body-content{color:var(--text-dark-primary);}
body.dark-mode .post-body-content blockquote{background:rgba(26,138,158,0.1);border-color:var(--accent);}
body.dark-mode .post-body-content a{color:#5eead4;}
body.dark-mode .post-tags{border-color:var(--border-dark);}
body.dark-mode .post-tags a{background:rgba(26,138,158,0.15);color:#5eead4;}
body.dark-mode .related-section{border-color:var(--border-dark);}
body.dark-mode .related-section h3{color:var(--text-dark-primary);}
body.dark-mode .related-card{background:var(--bg-dark-card);border-color:var(--border-dark);}
body.dark-mode .related-card h4{color:var(--text-dark-primary);}
body.dark-mode .footer-wrap{background:var(--bg-dark-card);border-color:var(--border-dark);}
body.dark-mode .footer-wrap,.dark-mode .footer-wrap a{color:var(--text-dark-secondary);}
body.dark-mode .footer-about h3{color:#5eead4;}
body.dark-mode .footer-bottom{border-color:var(--border-dark);}
body.dark-mode .breadcrumb a,.dark-mode .breadcrumb span{color:var(--text-dark-secondary);}
body.dark-mode .comments-block{border-color:var(--border-dark);}
body.dark-mode .comments-block h3{color:var(--text-dark-primary);}
body.dark-mode .archive-list li{border-color:var(--border-dark);}
body.dark-mode .archive-list a{color:var(--text-dark-secondary);}
body.dark-mode .sidebar-copyright{color:var(--text-dark-secondary);}
body.dark-mode .mobile-overlay.active{background:rgba(0,0,0,0.7);}
body.dark-mode .close-sb{background:var(--bg-dark-card);border-color:var(--border-dark);color:var(--text-dark-primary);}
body.dark-mode .view-all{color:#5eead4;}

/* ========== SIDEBAR LEFT ========== */
.sidebar-left{
  position:fixed;top:0;left:0;bottom:0;width:var(--sidebar-w);
  background:var(--bg-sidebar);border-right:1px solid var(--border);
  display:flex;flex-direction:column;z-index:200;
  overflow-y:auto;overflow-x:hidden;
}
.sidebar-left::-webkit-scrollbar{width:3px;}
.sidebar-left::-webkit-scrollbar-thumb{background:rgba(0,0,0,0.1);border-radius:3px;}
.sidebar-inner{padding:28px 20px 16px;flex:1;display:flex;flex-direction:column;}
.sidebar-brand{text-align:center;margin-bottom:28px;padding-bottom:20px;border-bottom:1px solid rgba(0,0,0,0.06);}
.sidebar-brand h2{font-family:var(--font-serif);font-size:1.45rem;color:var(--accent);font-weight:700;letter-spacing:-0.3px;font-style:italic;}
.sidebar-brand p{font-size:0.78rem;color:var(--text-secondary);margin-top:4px;letter-spacing:0.2px;}
.search-box{margin-bottom:24px;position:relative;}
.search-box .s-ico{position:absolute;left:13px;top:50%;transform:translateY(-50%);width:15px;height:15px;color:var(--text-muted);pointer-events:none;}
.search-box input{
  width:100%;padding:10px 14px 10px 38px;
  background:rgba(255,255,255,0.75);border:1px solid rgba(0,0,0,0.08);
  border-radius:var(--radius-full);font-size:0.84rem;color:var(--text-primary);
  outline:none;transition:all var(--tr);font-family:var(--font-sans);
}
.search-box input:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(26,138,158,0.1);background:#fff;}
.sidebar-nav{margin-bottom:auto;}
.sidebar-nav li{margin-bottom:2px;}
.sidebar-nav a{
  display:flex;align-items:center;gap:12px;
  padding:10px 14px;border-radius:var(--radius-sm);
  font-size:0.88rem;font-weight:500;color:var(--text-primary);
  transition:all var(--tr);
}
.sidebar-nav a:hover{background:var(--accent-light);color:var(--accent);}
.sidebar-nav .n-ico{width:20px;height:20px;flex-shrink:0;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;}
.sidebar-copyright{text-align:center;font-size:0.72rem;color:var(--text-muted);padding:16px 0 4px;border-top:1px solid rgba(0,0,0,0.06);margin-top:16px;}
.close-sb{
  display:none;position:absolute;top:12px;right:12px;
  width:30px;height:30px;border-radius:50%;border:1px solid var(--border);
  background:var(--bg-card);cursor:pointer;font-size:1rem;
  color:var(--text-secondary);align-items:center;justify-content:center;line-height:1;
}

/* ========== TOPBAR ========== */
.topbar{
  position:fixed;top:0;left:var(--sidebar-w);right:0;height:var(--topbar-h);
  background:var(--bg-card);border-bottom:1px solid var(--border);
  display:flex;align-items:center;padding:0 20px;gap:10px;z-index:150;
}
.mobile-btn{
  display:none;width:36px;height:36px;border:none;background:transparent;
  font-size:1.3rem;color:var(--text-primary);cursor:pointer;
  align-items:center;justify-content:center;flex-shrink:0;
}
.pill-arrow{
  width:30px;height:30px;border-radius:50%;border:1px solid var(--border);
  background:var(--bg-card);cursor:pointer;display:flex;align-items:center;
  justify-content:center;font-size:0.85rem;color:var(--text-secondary);
  flex-shrink:0;transition:all var(--tr);
}
.pill-arrow:hover{border-color:var(--accent);color:var(--accent);}
.pill-wrap{flex:1;overflow:hidden;min-width:0;}
.pill-nav{
  display:flex;gap:8px;overflow-x:auto;scroll-behavior:smooth;
  -ms-overflow-style:none;scrollbar-width:none;padding:3px 0;
}
.pill-nav::-webkit-scrollbar{display:none;}
.pill-nav a{
  flex-shrink:0;padding:7px 20px;border-radius:var(--radius-full);
  border:1px solid var(--border);background:var(--bg-card);
  font-size:0.84rem;font-weight:500;color:var(--text-secondary);
  white-space:nowrap;transition:all var(--tr);
}
.pill-nav a:hover,.pill-nav a.active{background:var(--accent);border-color:var(--accent);color:#fff;}
.topbar-actions{display:flex;gap:8px;align-items:center;flex-shrink:0;}
.theme-btn{
  width:34px;height:34px;border-radius:50%;border:1px solid var(--border);
  background:var(--bg-card);cursor:pointer;display:flex;align-items:center;
  justify-content:center;font-size:1rem;color:var(--text-secondary);
  transition:all var(--tr);flex-shrink:0;
}
.theme-btn:hover{border-color:var(--accent);color:var(--accent);}

/* ========== MAIN LAYOUT ========== */
.main-wrapper{margin-left:var(--sidebar-w);padding-top:var(--topbar-h);min-height:100vh;display:flex;flex-direction:column;}
.content-area{max-width:1400px;width:100%;margin:0 auto;padding:28px 24px;display:flex;gap:28px;flex:1;}
.main-content{flex:1;min-width:0;}
.main-content-inner{
  background:var(--bg-card);border-radius:var(--radius);
  border:1px solid var(--border);box-shadow:var(--shadow-sm);
  padding:28px 24px;
}

/* ========== SIDEBAR RIGHT ========== */
.sidebar-right{width:var(--sidebar-r-w);flex-shrink:0;}
.sidebar-r-box{
  position:sticky;top:calc(var(--topbar-h) + 28px);
  background:var(--bg-card);border-radius:var(--radius);
  border:1px solid var(--border);box-shadow:var(--shadow-sm);
  padding:24px 20px;
}
.sb-section{margin-bottom:28px;}
.sb-section:last-child{margin-bottom:0;}
.sb-title{
  font-size:0.73rem;font-weight:700;text-transform:uppercase;
  letter-spacing:1.8px;color:var(--accent);margin-bottom:16px;
  display:block;position:relative;padding-bottom:12px;
}
.sb-title::after{content:'';position:absolute;left:0;bottom:0;width:100%;height:1px;background:var(--border);}
.pop-item{display:flex;align-items:flex-start;gap:12px;padding:12px 0;border-bottom:1px solid var(--border);}
.pop-item:last-child{border-bottom:none;padding-bottom:0;}
.pop-num{
  width:30px;height:30px;border-radius:50%;
  background:var(--accent);color:#fff;
  font-size:0.75rem;font-weight:700;flex-shrink:0;
  display:flex;align-items:center;justify-content:center;margin-top:1px;
}
.pop-info{flex:1;min-width:0;}
.pop-title{font-size:0.84rem;font-weight:600;line-height:1.4;color:var(--text-primary);display:block;}
.pop-title:hover{color:var(--accent);}
.pop-date{font-size:0.72rem;color:var(--text-muted);margin-top:3px;}
.cat-cloud{display:flex;flex-wrap:wrap;gap:7px;}
.cat-pill{
  display:inline-block;padding:6px 16px;
  background:var(--accent-light);color:var(--accent);
  border-radius:var(--radius-full);font-size:0.8rem;font-weight:500;
  transition:all var(--tr);
}
.cat-pill:hover{background:var(--accent);color:#fff;}
.archive-list li{padding:7px 0;border-bottom:1px solid var(--border);font-size:0.84rem;}
.archive-list li:last-child{border-bottom:none;}
.archive-list a{color:var(--text-secondary);}
.archive-list a:hover{color:var(--accent);}

/* ========== GRID SECTIONS ========== */
.grid-section{margin-bottom:36px;}
.grid-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;}
.grid-title{
  font-family:var(--font-serif);font-size:1.45rem;font-weight:700;
  color:var(--text-primary);padding-left:16px;position:relative;
}
.grid-title::before{
  content:'';position:absolute;left:0;top:3px;bottom:3px;
  width:4px;border-radius:2px;background:var(--accent);
}
.view-all{font-size:0.84rem;font-weight:600;color:var(--accent);display:flex;align-items:center;gap:4px;transition:color var(--tr);}
.view-all:hover{color:var(--accent-hover);}

/* Overlay Card */
.ov-card{position:relative;border-radius:var(--radius-sm);overflow:hidden;display:block;}
.ov-card img{width:100%;height:100%;object-fit:cover;transition:transform 0.5s var(--ease);}
.ov-card:hover img{transform:scale(1.04);}
.ov-info{position:absolute;bottom:0;left:0;right:0;padding:16px;background:linear-gradient(0deg,rgba(0,0,0,0.72) 0%,rgba(0,0,0,0.08) 70%,transparent 100%);}
.ov-cat{display:inline-block;padding:3px 10px;background:var(--accent);color:#fff;border-radius:4px;font-size:0.68rem;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:6px;}
.ov-ttl{color:#fff;font-size:0.84rem;font-weight:600;line-height:1.35;}
.ov-ttl.lg{font-size:1.15rem;line-height:1.3;}
.ov-date{color:rgba(255,255,255,0.75);font-size:0.72rem;margin-top:3px;}

/* 1. BENTO BOX */
.bento-grid{display:grid;grid-template-columns:1.6fr 1fr 1fr;grid-template-rows:195px 195px;gap:10px;}
.bento-grid .b-1{grid-column:1;grid-row:1/3;}
.bento-grid .b-2{grid-column:2;grid-row:1;}
.bento-grid .b-3{grid-column:3;grid-row:1;}
.bento-grid .b-4{grid-column:2;grid-row:2;}
.bento-grid .b-5{grid-column:3;grid-row:2;}

/* 2. EDITORIAL HERO */
.ed-grid{display:grid;grid-template-columns:1.5fr 1fr;grid-template-rows:195px 195px;gap:10px;}
.ed-grid .e-1{grid-row:1/3;}
.ed-grid .e-2{grid-column:2;grid-row:1;}
.ed-grid .e-3{grid-column:2;grid-row:2;}
.ed-extra{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px;}

/* 3. JUSTIFIED FLICKR */
.jf-grid{display:flex;flex-wrap:wrap;gap:8px;}
.jf-grid .jf-item{flex:1 1 auto;height:200px;min-width:130px;}
.jf-grid .jf-item:nth-child(1){flex-basis:40%;}
.jf-grid .jf-item:nth-child(2){flex-basis:28%;}
.jf-grid .jf-item:nth-child(3){flex-basis:28%;}
.jf-grid .jf-item:nth-child(4){flex-basis:48%;}
.jf-grid .jf-item:nth-child(5){flex-basis:48%;}

/* 4. SQUARE INSTAGRAM */
.sq-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;}
.sq-item{aspect-ratio:1;border-radius:var(--radius-sm);overflow:hidden;position:relative;display:block;}
.sq-item img{width:100%;height:100%;object-fit:cover;transition:transform 0.5s var(--ease);}
.sq-item:hover img{transform:scale(1.06);}
.sq-ov{position:absolute;inset:0;background:transparent;display:flex;align-items:flex-end;padding:10px;transition:background var(--tr);}
.sq-item:hover .sq-ov{background:rgba(0,0,0,0.45);}
.sq-ov span{color:#fff;font-size:0.78rem;font-weight:600;opacity:0;transform:translateY(6px);transition:all var(--tr);}
.sq-item:hover .sq-ov span{opacity:1;transform:translateY(0);}

/* 5. ASYMMETRIC */
.as-grid{display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:230px 200px;gap:10px;}
.as-grid .a-1{grid-column:1/3;grid-row:1;}
.as-grid .a-2{grid-column:3;grid-row:1;margin-top:25px;}
.as-grid .a-3{grid-column:1;grid-row:2;margin-top:-25px;}
.as-grid .a-4{grid-column:2/4;grid-row:2;}

/* ========== ARTICLE CARDS (index) ========== */
.cards-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:28px;}
.article-card{
  background:var(--bg-card);border-radius:var(--radius);overflow:hidden;
  border:1px solid var(--border);box-shadow:var(--shadow-sm);
  transition:all var(--tr);
}
.article-card:hover{box-shadow:var(--shadow-lg);transform:translateY(-3px);}
.card-thumb{width:100%;height:180px;object-fit:cover;}
.card-body{padding:16px;}
.card-cat{
  display:inline-block;padding:3px 10px;background:var(--accent-light);color:var(--accent);
  border-radius:4px;font-size:0.7rem;font-weight:600;text-transform:uppercase;
  letter-spacing:0.4px;margin-bottom:8px;
}
.card-title a{
  font-family:var(--font-serif);font-size:1rem;font-weight:600;line-height:1.45;
  color:var(--text-primary);display:-webkit-box;-webkit-line-clamp:2;
  -webkit-box-orient:vertical;overflow:hidden;
}
.card-title a:hover{color:var(--accent);}
.card-excerpt{
  font-size:0.83rem;color:var(--text-secondary);margin-top:8px;line-height:1.55;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;
}
.card-meta{
  display:flex;align-items:center;justify-content:space-between;
  margin-top:14px;padding-top:12px;border-top:1px solid var(--border);
  font-size:0.74rem;color:var(--text-muted);
}

/* ========== SINGLE POST ========== */
.post-wrap{max-width:100%;}
.breadcrumb{font-size:0.84rem;color:var(--text-muted);margin-bottom:20px;display:flex;flex-wrap:wrap;gap:4px;}
.breadcrumb a{color:var(--accent);}
.breadcrumb a:hover{text-decoration:underline;}
.post-title-single{
  font-family:var(--font-serif);font-size:2rem;font-weight:700;
  line-height:1.3;color:var(--text-primary);margin-bottom:16px;
}
.post-meta-s{
  display:flex;gap:16px;flex-wrap:wrap;align-items:center;
  font-size:0.85rem;color:var(--text-secondary);
  margin-bottom:24px;padding-bottom:18px;border-bottom:1px solid var(--border);
}
.post-featured-img{width:100%;height:auto;border-radius:var(--radius-sm);margin-bottom:28px;}
.post-body-content{font-size:1.02rem;line-height:1.85;color:var(--text-primary);}
.post-body-content h2,.post-body-content h3{font-family:var(--font-serif);margin:28px 0 14px;font-weight:700;}
.post-body-content h2{font-size:1.5rem;}
.post-body-content h3{font-size:1.25rem;}
.post-body-content p{margin-bottom:16px;}
.post-body-content img{border-radius:var(--radius-sm);margin:20px 0;}
.post-body-content a{color:var(--accent);text-decoration:underline;}
.post-body-content blockquote{
  border-left:4px solid var(--accent);padding:16px 20px;margin:20px 0;
  background:var(--accent-light);border-radius:0 var(--radius-sm) var(--radius-sm) 0;font-style:italic;
}
.post-body-content ul,.post-body-content ol{margin:0 0 16px 24px;}
.post-body-content ul{list-style:disc;}
.post-body-content ol{list-style:decimal;}
.post-body-content li{margin-bottom:6px;}
.post-body-content pre{background:#1e293b;color:#e2e8f0;padding:16px;border-radius:var(--radius-sm);overflow-x:auto;margin:18px 0;font-size:0.9rem;}
.post-body-content code{font-family:'Fira Code',monospace;font-size:0.9em;}
.post-tags{display:flex;flex-wrap:wrap;gap:7px;margin-top:28px;padding-top:20px;border-top:1px solid var(--border);}
.post-tags a{
  display:inline-block;padding:6px 16px;background:var(--accent-light);color:var(--accent);
  border-radius:var(--radius-full);font-size:0.8rem;font-weight:500;transition:all var(--tr);
}
.post-tags a:hover{background:var(--accent);color:#fff;}

/* ========== RELATED POSTS ========== */
.related-section{margin-top:40px;padding-top:28px;border-top:1px solid var(--border);}
.related-section h3{font-family:var(--font-serif);font-size:1.25rem;font-weight:700;margin-bottom:18px;color:var(--text-primary);}
.related-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;}
.related-card{
  background:var(--bg-card);border-radius:var(--radius-sm);overflow:hidden;
  border:1px solid var(--border);transition:all var(--tr);display:block;
}
.related-card:hover{box-shadow:var(--shadow-md);transform:translateY(-2px);}
.related-card img{width:100%;height:140px;object-fit:cover;}
.related-card h4{
  padding:12px 14px;font-size:0.86rem;font-weight:600;line-height:1.4;color:var(--text-primary);
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;
}

/* ========== COMMENTS ========== */
.comments-block{margin-top:36px;padding-top:24px;border-top:1px solid var(--border);}
.comments-block h3{font-family:var(--font-serif);font-size:1.25rem;font-weight:700;margin-bottom:16px;}

/* ========== SCROLL TO TOP ========== */
.scroll-top{
  position:fixed;bottom:28px;right:28px;width:46px;height:46px;border-radius:50%;
  background:var(--accent);color:#fff;border:none;cursor:pointer;
  display:none;align-items:center;justify-content:center;font-size:1.2rem;
  box-shadow:0 4px 16px rgba(26,138,158,0.35);transition:all var(--tr);z-index:500;
}
.scroll-top.show{display:flex;}
.scroll-top:hover{transform:translateY(-3px);box-shadow:0 6px 24px rgba(26,138,158,0.5);}

/* ========== PAGINATION ========== */
.pager{display:flex;justify-content:space-between;margin-top:28px;padding-top:20px;border-top:1px solid var(--border);}
.pager a{color:var(--accent);font-weight:600;font-size:0.9rem;transition:color var(--tr);}
.pager a:hover{color:var(--accent-hover);}

/* ========== FOOTER ========== */
.footer-wrap{background:var(--bg-card);border-top:1px solid var(--border);margin-top:50px;padding:36px 24px 18px;}
.footer-inner{max-width:1100px;margin:0 auto;display:grid;grid-template-columns:2fr 1fr 1fr;gap:36px;}
.footer-about h3{font-family:var(--font-serif);font-size:1.1rem;color:var(--accent);margin-bottom:10px;}
.footer-about p{font-size:0.85rem;color:var(--text-secondary);line-height:1.6;}
.footer-links h4{font-size:0.78rem;font-weight:700;margin-bottom:12px;text-transform:uppercase;letter-spacing:1px;color:var(--text-primary);}
.footer-links ul{list-style:none;}
.footer-links li{margin-bottom:7px;}
.footer-links a{font-size:0.85rem;color:var(--text-secondary);}
.footer-links a:hover{color:var(--accent);}
.footer-bottom{text-align:center;margin-top:24px;padding-top:16px;border-top:1px solid var(--border);font-size:0.78rem;color:var(--text-muted);}

/* ========== MOBILE ========== */
.mobile-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:195;}
.mobile-overlay.active{display:block;}

@media(max-width:1100px){
  .sidebar-right{display:none;}
  .cards-grid{grid-template-columns:repeat(2,1fr);}
  .related-grid{grid-template-columns:repeat(2,1fr);}
  .sq-grid{grid-template-columns:repeat(3,1fr);}
  .bento-grid{grid-template-columns:1fr 1fr;grid-template-rows:auto;}
  .bento-grid .b-1{grid-column:1/3;}
  .ed-grid{grid-template-columns:1fr;grid-template-rows:auto;}
  .ed-grid .e-1{grid-row:auto;}
  .as-grid{grid-template-columns:1fr 1fr;grid-template-rows:auto;}
  .as-grid .a-1{grid-column:1/3;}.as-grid .a-2{margin-top:0;}.as-grid .a-3{margin-top:0;}.as-grid .a-4{grid-column:auto;}
  .footer-inner{grid-template-columns:1fr;}
}
@media(max-width:768px){
  :root{--sidebar-w:0px;}
  .sidebar-left{transform:translateX(-100%);width:275px;transition:transform var(--tr);background:var(--bg-sidebar);}
  .sidebar-left.open{transform:translateX(0);}
  .close-sb{display:flex;}
  .mobile-btn{display:flex;}
  .mobile-overlay.active{display:block;}
  .topbar{left:0;}
  .main-wrapper{margin-left:0;}
  .content-area{padding:14px;gap:14px;}
  .main-content-inner{padding:18px 14px;}
  .cards-grid{grid-template-columns:1fr;margin-top:20px;}
  .related-grid{grid-template-columns:1fr;}
  .sq-grid{grid-template-columns:repeat(2,1fr);}
  .jf-grid .jf-item{min-width:100%;height:170px;}
  .bento-grid{grid-template-columns:1fr;grid-template-rows:auto;}
  .bento-grid .b-1{grid-column:1;}
  .post-title-single{font-size:1.5rem;}
  .scroll-top{bottom:18px;right:18px;width:40px;height:40px;font-size:1rem;}
}

body.script:
//

// Copyright sidebar + footer
(function(){
  var sc=document.getElementById('sidebarCopy');
  var fy=document.getElementById('footerYear');
  var t=document.querySelector('.sidebar-brand h2');
  var n=t?t.textContent:'Pena Edukasi';
  var y=new Date().getFullYear();
  if(sc)sc.textContent='\u00A9 '+y+' '+n;
  if(fy)fy.textContent='\u00A9 '+y+' '+n+'. All Rights Reserved.';
})();

// Dark Mode
(function(){
  var btn=document.getElementById('themeToggle');
  function setDark(d){
    if(d){document.body.classList.add('dark-mode');if(btn)btn.innerHTML='&#9788;';try{localStorage.setItem('pe-dm','1');}catch(e){}}
    else{document.body.classList.remove('dark-mode');if(btn)btn.innerHTML='&#9789;';try{localStorage.setItem('pe-dm','0');}catch(e){}}
  }
  try{if(localStorage.getItem('pe-dm')==='1')setDark(true);}catch(e){}
  if(btn)btn.addEventListener('click',function(){setDark(!document.body.classList.contains('dark-mode'));});
})();

// Pill Nav Scroll
(function(){
  var nav=document.getElementById('pillNav');
  var left=document.getElementById('pillLeft');
  var right=document.getElementById('pillRight');
  if(!nav)return;
  if(left)left.addEventListener('click',function(){nav.scrollBy({left:-200,behavior:'smooth'});});
  if(right)right.addEventListener('click',function(){nav.scrollBy({left:200,behavior:'smooth'});});
  var pills=nav.querySelectorAll('a');
  var loc=window.location.href;
  for(var i=0;i<pills.length;i++){
    pills[i].classList.remove('active');
    if(pills[i].href===loc)pills[i].classList.add('active');
  }
})();

// Scroll To Top
(function(){
  var btn=document.getElementById('scrollTopBtn');
  if(!btn)return;
  window.addEventListener('scroll',function(){
    if(window.scrollY>400)btn.classList.add('show');else btn.classList.remove('show');
  });
  btn.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'});});
})();

// Mobile Sidebar
(function(){
  var sb=document.getElementById('sidebarLeft');
  var ov=document.getElementById('mobileOverlay');
  var ob=document.getElementById('mobileBtn');
  var cb=document.getElementById('closeSb');
  function open(){if(sb)sb.classList.add('open');if(ov)ov.classList.add('active');}
  function close(){if(sb)sb.classList.remove('open');if(ov)ov.classList.remove('active');}
  if(ob)ob.addEventListener('click',open);
  if(cb)cb.addEventListener('click',close);
  if(ov)ov.addEventListener('click',close);
})();

// Feed Helper Functions
function peThumb(e){
  if(e.media$thumbnail)return e.media$thumbnail.url.replace(/\/s72-c/,'/s600');
  var c=e.content?e.content.$t:(e.summary?e.summary.$t:'');
  var m=c.match(/<img[^>]+src=["']([^"']+)/);
  return m?m[1]:'https://via.placeholder.com/600x400/1a8a9e/ffffff?text=Pena+Edukasi';
}
function peLink(e){for(var i=0;i<e.link.length;i++){if(e.link[i].rel==='alternate')return e.link[i].href;}return '#';}
function peTitle(e){return e.title.$t;}
function peCat(e){return e.category?e.category[0].term:'';}
function peDate(e){
  try{var d=new Date(e.published.$t);var m=['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'];return d.getDate()+' '+m[d.getMonth()]+' '+d.getFullYear();}
  catch(x){return '';}
}

// Overlay Card Builder
function peCard(e,cls,lg){
  var t=peTitle(e).replace(/"/g,'&amp;quot;');
  var tc=lg?'ov-ttl lg':'ov-ttl';
  return '<a href="'+peLink(e)+'" class="ov-card '+cls+'">'+
    '<img src="'+peThumb(e)+'" alt="'+t+'"/>'+
    '<div class="ov-info"><span class="ov-cat">'+peCat(e)+'</span>'+
    '<div class="'+tc+'">'+peTitle(e)+'</div>'+
    '<div class="ov-date">'+peDate(e)+'</div></div></a>';
}

// Fetch by Label
function peFetch(label,count,cb){
  var s=document.createElement('script');
  var fn='__pe_'+label.replace(/[^a-zA-Z0-9]/g,'')+'_'+Math.random().toString(36).substr(2,5);
  window[fn]=function(d){cb(d.feed?d.feed.entry||[]:[]);try{delete window[fn];}catch(x){window[fn]=undefined;}};
  s.src='/feeds/posts/summary/-/'+encodeURIComponent(label)+'?alt=json-in-script&max-results='+count+'&callback='+fn;
  document.body.appendChild(s);
}

// Grid 1: Bento (Pendidikan)
peFetch('Pendidikan',5,function(en){
  var g=document.getElementById('bentoGrid');if(!g||!en.length)return;
  var h='';var c=['b-1','b-2','b-3','b-4','b-5'];
  for(var i=0;i<Math.min(en.length,5);i++)h+=peCard(en[i],c[i]||'',i===0);
  g.innerHTML=h;
});

// Grid 2: Editorial (Kurikulum)
peFetch('Kurikulum',5,function(en){
  var g=document.getElementById('edGrid');if(!g||!en.length)return;
  var h=peCard(en[0],'e-1',true);
  if(en[1])h+=peCard(en[1],'e-2',false);
  if(en[2])h+=peCard(en[2],'e-3',false);
  g.innerHTML=h;
  if(en.length>3){
    var ex=document.createElement('div');ex.className='ed-extra';var eh='';
    for(var i=3;i<Math.min(en.length,5);i++)eh+=peCard(en[i],'',false);
    ex.innerHTML=eh;g.parentNode.appendChild(ex);
  }
});

// Grid 3: Justified (Materi)
peFetch('Materi',5,function(en){
  var g=document.getElementById('jfGrid');if(!g||!en.length)return;
  var h='';for(var i=0;i<Math.min(en.length,5);i++)h+=peCard(en[i],'jf-item',false);
  g.innerHTML=h;
});

// Grid 4: Square (Tutorial)
peFetch('Tutorial',5,function(en){
  var g=document.getElementById('sqGrid');if(!g||!en.length)return;
  var h='';
  for(var i=0;i<Math.min(en.length,5);i++){
    var t=peTitle(en[i]).replace(/"/g,'&amp;quot;');
    h+='<a href="'+peLink(en[i])+'" class="sq-item">'+
      '<img src="'+peThumb(en[i])+'" alt="'+t+'"/>'+
      '<div class="sq-ov"><span>'+peTitle(en[i])+'</span></div></a>';
  }
  g.innerHTML=h;
});

// Grid 5: Asymmetric (Madrasah)
peFetch('Madrasah',5,function(en){
  var g=document.getElementById('asGrid');if(!g||!en.length)return;
  var h='';var c=['a-1','a-2','a-3','a-4','a-5'];
  for(var i=0;i<Math.min(en.length,5);i++)h+=peCard(en[i],c[i]||'',i===0);
  g.innerHTML=h;
});

// 3 Related Posts (on single post page)
(function(){
  var c=document.getElementById('relatedPosts');if(!c)return;
  var tags=document.querySelectorAll('.post-tags a');var label='';
  if(tags.length>0)label=tags[0].textContent.replace('#','').trim();
  if(!label)return;
  var cur=window.location.href;
  var s=document.createElement('script');
  var fn='__peRel'+Math.random().toString(36).substr(2,5);
  window[fn]=function(d){
    var en=d.feed?d.feed.entry||[]:[]; var h=''; var ct=0;
    for(var i=0;i<en.length&&ct<3;i++){
      var lk=peLink(en[i]);if(lk===cur)continue;
      var t=peTitle(en[i]).replace(/"/g,'&amp;quot;');
      h+='<a href="'+lk+'" class="related-card">'+
        '<img src="'+peThumb(en[i])+'" alt="'+t+'"/>'+
        '<h4>'+peTitle(en[i])+'</h4></a>';
      ct++;
    }
    c.innerHTML=h;try{delete window[fn];}catch(x){window[fn]=undefined;}
  };
  s.src='/feeds/posts/summary/-/'+encodeURIComponent(label)+'?alt=json-in-script&max-results=4&callback='+fn;
  document.body.appendChild(s);
})();

//
